FJmXvJqMsQbmQdcmpGKcTtHTMTvrJqmfB"]]}, {"post": 5229423069, "liens": [["https://mail.google.com/mail/u/0/#sent/CllgCKCCSZfrrNrRmfflMntrSMjHvkMRMWWwmKRcSDnqdSmgBsSszgZqqRWJP...", "https://mail.google.com/mail/u/0/#sent/CllgCKCCSZfrrNrRmfflMntrSMjHvkMRMWWwmKRcSDnqdSmgBsSszgZqqRWJPGtPZhXfhXTLRRg"]]}, {"post": 5210435120, "liens": [["https://mail.google.com/mail/u/0/#inbox/WhctKLcDwkpPggKDxllHgTqgChhBZqRMStxNDfpPfKrBfBpFNkpKPMZFRnPm...", "https://mail.google.com/mail/u/0/#inbox/WhctKLcDwkpPggKDxllHgTqgChhBZqRMStxNDfpPfKrBfBpFNkpKPMZFRnPmhLldCfmXvgL"], ["https://mail.google.com/mail/u/0/#sent/DmwnWtMjKKSJHMRRzRmwKhWRSpWrXkdwKFvlSkmjJbWQFpWCnwJwVzrwbsDCj...", "https://mail.google.com/mail/u/0/#sent/DmwnWtMjKKSJHMRRzRmwKhWRSpWrXkdwKFvlSkmjJbWQFpWCnwJwVzrwbsDCjmxtbdKzmSPNDpZq"]]}]$monday$::jsonb) loop
    select contenu into c from pilotage.travaux_monday_notes where monday_post_id = (r->>'post')::bigint;
    continue when c is null;
    for l in select * from jsonb_array_elements(r->'liens') loop
      c := replace(c, l->>0, l->>1);
    end loop;
    update pilotage.travaux_monday_notes set contenu = c where monday_post_id = (r->>'post')::bigint;
  end loop;
end $$;

update pilotage.travaux_monday_notes n set contenu = x.contenu, tronque = false
from jsonb_to_recordset($monday$[{"post": 4481342008, "contenu": "État des lieux – éléments détériorés - appartement Fleury Mérogis\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30\n\n---------- Forwarded message ---------\nDe : UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com>\nDate: ven. 5 sept. 2025 à 17:02\nSubject: Re: État des lieux – éléments détériorés - appartement Fleury Mérogis\nTo: Elise Levasseur <elise.levasseur28@gmail.com>\n\nBonjour Madame Levasseur,\n\nJe vous en prie.\n\nPour toute demande concernant l'installation de portes sur l'armoire, je préfère que vous passiez par nous. Cela nous permettra d'assurer un suivi précis de votre dossier et d'éviter toute discussion inutile.\n\nBien cordialement,\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30\n\nLe ven. 5 sept. 2025 à 16:53, Elise Levasseur <elise.levasseur28@gmail.com> a écrit :\n\nBonjour,\n\nMerci pour votre retour et vos réponses !\n\nPour l’installation de portes sur l’armoire, puis-je contacter directement la propriétaire par mail, pour avoir son accord écrit ? Ou je vois directement avec l’agence ?\n\nBien cordialement,\nElise Levasseur \n\nLe ven. 5 sept. 2025 à 15:13, UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com> a écrit :\n\nBonjour Mme Levasseur,\nNous faisons suite à votre courriel concernant les équipements présents dans votre logement situé 102 Rue Anaïs Nin à Fleury-Mérogis  et nous vous remercions de nous avoir contactés.\n\nNous confirmons que bien que votre contrat soit un bail d'habitation non meublé, les appareils électroménagers ainsi que la penderie de la chambre sont bien listés dans l'état des lieux d'entrée. De ce fait, ils sont considérés comme mis à votre disposition par la propriétaire et entrent dans le cadre des obligations du bailleur.\n\nPour répondre précisément à vos questions :\n\nConcernant les appareils électroménagers (four, frigo, etc.) : Si une panne survient en raison de l'usure normale (vétusté), la réparation ou le remplacement de l'appareil est de la responsabilité de la propriétaire. Votre responsabilité en tant que locataire couvre l'entretien courant des appareils et les éventuelles pannes dues à une mauvaise utilisation.\n\nConcernant l'armoire de la chambre : L'état des lieux mentionne bien \"1 penderie\". S'agissant d'un bien mis à disposition, toute modification substantielle, comme l'ajout de portes, nécessite l'accord écrit et préalable de la propriétaire. Si elle accepte, les frais relatifs à cette modification seraient à votre charge.\n\nPar ailleurs, nous avons bien noté le dysfonctionnement de la bonde de la baignoire, signalé dans l'état des lieux d'entrée comme étant \"HS, Tige non adaptée\".\n\nNous avons transmis vos coordonnées à la propriétaire, Madame JOUANDEAU, qui va prendre directement contact avec vous afin de convenir d'un rendez-vous pour procéder à la réparation.\n\nNous restons à votre disposition pour toute question complémentaire.\n\nCordialement,\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30\n\nLe jeu. 4 sept. 2025 à 09:20, Elise Levasseur <elise.levasseur28@gmail.com> a écrit :\n\nBonjour,\n\nJ’aurais une question complémentaire concernant les équipements électroménagers ainsi que l’armoire présente dans la chambre.\n\nPourriez-vous m’indiquer si ces éléments ont été rachetés par la propriétaire, ou bien s’ils ont été laissés par l’ancienne locataire ?\n\nEn effet, si je dois remplacer un équipement défectueux ou apporter une modification à l’armoire (par exemple en y ajoutant des portes), je souhaiterais savoir si les frais correspondants relèvent de la responsabilité de la propriétaire ou du locataire.\n\nDans l’attente de votre retour,\n\nBien cordialement,\n\nElise Levasseur\n\nLe mer. 3 sept. 2025 à 17:35, UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com> a écrit :\n\nBonjour Madame Levasseur,\n\nJe fais suite à votre email concernant l'état des lieux de l'appartement de Fleury-Mérogis.\n\nJe tiens à vous informer que l'ensemble des remarques que vous avez soulevées concernant les éléments détériorés ou manquants sont effectivement mentionnées dans l'état des lieux d'entrée, à l'exception de la vis du pied de l'îlot central de la cuisine.\n\nConcernant le mécanisme de bonde de la baignoire, je reviendrai vers vous très rapidement vers pour ce point.\n\nBien cordialement,\n\nVotre Gestionnaire\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30\n\nLe mer. 3 sept. 2025 à 15:53, Elise Levasseur <elise.levasseur28@gmail.com> a écrit :\n\nBonjour,\n\nÀ la suite de l'état des lieux réalisé le 02/09 dans l’appartement situé au 102 rue Anaïs Rin à Fleury-Mérogis, nous avons constaté que certains éléments étaient détériorés, abîmés ou manquants.\n\nNous souhaiterions savoir s’il appartient au locataire de prendre en charge leur remplacement/réparation, ou si cela relève de la responsabilité de la propriétaire.\n\nVoici la liste des points relevés :\n\nLa bonde de la baignoire ne fonctionne plus (cassée ou bloquée), car il n’est plus possible d’utiliser la molette pour évacuer ou retenir l’eau.\n\nLes rails coulissants du réfrigérateur sont cassés et ne permettent plus l'ouverture simultanée des portes.\n\nL’intérieur d'un des tiroirs du meuble de salle de bain est détérioré.\n\nUn pied manque à l’îlot central de la cuisine (manque de stabilité). Il n'a pas été relevé durant l'état des lieux avec la société EDL. \n\nL’ampoule du four ne fonctionne pas (sous réserve de son fonctionnement lors de la mise route du four). \n\nDans l’attente de votre retour,\n\nBien cordialement,\n\nElise LEVASSEUR\n\n06 47 00 30 31"}, {"post": 4878543343, "contenu": "reponse du bailleur\n\nhttps://mail.google.com/mail/u/0/#inbox/jrjtXLDsrfzCpTgHnBCFvwPfZHBMGQKvqpmDHPPfmhMWJVqJZxjjSTRWmQNxqpGnbbXqwFdD\n\nBonjour,\nIl a effectivement mon numéro car je l'avais prévenu que j'étais la présidente de la copropriété. S'il y avait un souci dans la copropriété, je suis l'interlocutrice pour remonter les infos au syndic de copro.Bref, les appels concernant les soucis relevés ont été:- une fuite au sous sol, dont le syndic avait été informé puisque cela avait été réparé.- une autre fuite au sous sol, au niveau d'un tuyau concernant les eaux fluviales (à ses dires) Je ne lui ai rien demandé, il m'a prévenu qu'il avait mis lui-même du joint. J'en avais informé Mr Berthon du syndic lorsque je lui avais demandé de faire le tour de la propriété pour faire le point sur les quelques réparations extérieures à effectuer au sein de la copro.- le grand portail d'entrée qui ne fonctionnait plus, des lampes extérieures qui ne fonctionnaient plus- Il a pris l'initiative de nettoyer les escaliers extérieurs allant au sous sol- Il a emmené à la déchèterie ce qu'il avait laissé au local à poubelles (j'avais eu des remontés de quelques propriétaires) et il m'avait appelé pour me demander s'il pouvait mettre également le salon de jardin pour m'éviter d'y aller.- une fissure sur le côté du mur de la copropriété- l'accident d'un locataire qui a raflé le mur extérieur et qui a terminé sa course chez le voisin d'en face. - la VMC serait visiblement trop forte et aspirerait l'air chaud dans l'appartement et il y a un bruit de sifflement- une fissure au plafond de la chambre- les taches au plafond de la chambre- Il y aurait un taux d'humidité dans la salle de bain, car il a un appareil de mesure. Cela irait mieux depuis qu'il a mis un déshumidificateur.\n- demande concernant l'augmentation du loyer ( je lui ai répondu de voir avec l'agence)\nConcernant les taches au plafond dans les angles de la chambre, j'ai prévenu mon assurance et celle ci a fait intervenir un professionnel afin de constater s'il y avait des fuites ou infiltrations.Il en avait déduit une histoire de pont thermique dû à l'aération, éventuellement la VMC.Concernant la salle de bain, il avait dit qu'il fallait refaire les joints de carrelage. \n- dernièrement, il y aurait un gros problème concernant les murs de la salle de bain, mais je ne sais pas quoi, car je n'avais pas répondu.\nJe reste disponible verbalement si des points ne sont pas compréhensibles.\nCordialement\nMadame PANIC"}, {"post": 5663106714, "contenu": "Ordre de mission UDI Gestion - Sinistre au 9 Square Winston Churchill, 03100 Montluçon\n         Ordre de Mission\n Bonjour,\n\nSuite à un sinistre déclaré, nous vous mandatons par la présente pour effectuer les travaux de remise en état nécessaires dans le bien que nous gérons.\n\n Détails de l'intervention\n Nature du sinistre : toilet local commercial: fuite d'eau provenant de la cage d'escalier\n\nNature du bien : Local commercial\n\nAdresse du bien : 9 Square Winston Churchill, 03100 Montluçon\n\nMoyen d'accès : Contacter locataire\n\n  Référence à rappeler\n Merci d'indiquer impérativement la référence suivante sur tous vos devis et factures :\n\nTURPAULT Léo-Paul et TURPAULT Camille / UDI GESTION - 2 rue Charles Drezet 91100 Corbeil-Essonnes. Adresse d'intervention: 9 Square Winston Churchill, 03100 Montluçon\n\n  Contact Locataire\n Nom : BALDONI Claire - L30\n\nAdresse : 9 Square Winston Churchill, 03100 Montluçon\n\nTéléphone : 611447167\n\n Nous vous remercions de bien vouloir prendre contact avec le locataire pour convenir d'un rendez-vous et de nous transmettre votre devis dans les plus brefs délais.\n\nVeuillez également nous accuser réception de cet ordre de mission.\n\nCordialement,\n\nL'équipe UDI Gestion\n\n    UDI Gestion\n                SAS au capital de 1000 € - RCS: EVRY n° 907 631 170\n                Siège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\n                N° TVA Intra-communautaire: FR23907631170\n                Carte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\n                Numéro Orias n° 23006870\n\n                Assurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\n                Garantie financière: QBE Insurance (400 000 €)\n                Médiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr   \n Vos données personnelles (RGPD) — Les données que vous nous communiquez (par email ou via nos portails partenaires : Leboncoin, SeLoger…) sont traitées par Patrimoine Gestion Vedrines (agence UDI Corbeil-Essonnes) pour gérer vos demandes et transactions. Elles sont conservées selon les durées légales et réservées à notre personnel habilité. Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation et d'opposition, à exercer auprès de nvedrines@udi-immo.com. Pour en savoir plus ou introduire une réclamation auprès de la CNIL, consultez notre politique de confidentialité : https://udi-immo.com/donnees-personnelles/"}, {"post": 5638278418, "contenu": "Ordre de mission UDI Gestion - Sinistre au 71-73 Rue de la Dauphine, 91100 Corbeil-Essonnes\n         Ordre de Mission\n Bonjour,\n\nSuite à un sinistre déclaré, nous vous mandatons par la présente pour effectuer les travaux de remise en état nécessaires dans le bien que nous gérons.\n\n Détails de l'intervention\n Nature du sinistre : fuite d'eau plafond et toilette\n\nNature du bien : Appartement\n\nAdresse du bien : 71-73 Rue de la Dauphine, 91100 Corbeil-Essonnes\n\nMoyen d'accès : Contacter locataire\n\n  Référence à rappeler\n Merci d'indiquer impérativement la référence suivante sur tous vos devis et factures :\n\nHIREL Soizic / UDI GESTION - 2 rue Charles Drezet 91100 Corbeil-Essonnes. Adresse d'intervention: 71-73 Rue de la Dauphine, 91100 Corbeil-Essonnes\n\n  Contact Locataire\n Nom : GURWINDER Singh - L126\n\nAdresse : 71-73 Rue de la Dauphine, 91100 Corbeil-Essonnes\n\nTéléphone : 761263863\n\n Nous vous remercions de bien vouloir prendre contact avec le locataire pour convenir d'un rendez-vous et de nous transmettre votre devis dans les plus brefs délais.\n\nVeuillez également nous accuser réception de cet ordre de mission.\n\nCordialement,\n\nL'équipe UDI Gestion\n\n    UDI Gestion\n                SAS au capital de 1000 € - RCS: EVRY n° 907 631 170\n                Siège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\n                N° TVA Intra-communautaire: FR23907631170\n                Carte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\n                Numéro Orias n° 23006870\n\n                Assurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\n                Garantie financière: QBE Insurance (400 000 €)\n                Médiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr   \n Vos données personnelles (RGPD) — Les données que vous nous communiquez (par email ou via nos portails partenaires : Leboncoin, SeLoger…) sont traitées par Patrimoine Gestion Vedrines (agence UDI Corbeil-Essonnes) pour gérer vos demandes et transactions. Elles sont conservées selon les durées légales et réservées à notre personnel habilité. Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation et d'opposition, à exercer auprès de nvedrines@udi-immo.com. Pour en savoir plus ou introduire une réclamation auprès de la CNIL, consultez notre politique de confidentialité : https://udi-immo.com/donnees-personnelles/"}, {"post": 5413967971, "contenu": "recapitilatif procedure\n\nBonjour à tous,\n\nVous trouverez ci-dessous un récapitulatif de la procédure en cours concernant le dossier de M. YAKUT.\n\n1. Commandement de payer visant la clause résolutoire\n 06 juillet 2026 : délivrance par Commissaire de Justice d'un commandement de payer visant la clause résolutoire pour un montant de 4 058,52 €.\nLe délai légal de régularisation est de 6 semaines.\nÉchéance du commandement : 17 août 2026 à minuit.\nÀ compter du 18 août 2026, si les causes du commandement ne sont pas intégralement réglées, la clause résolutoire pourra être invoquée devant le juge.\n 2. Défaut d'assurance habitation\n Lors de nos vérifications, il est apparu que le contrat d'assurance habitation du locataire a été résilié. À ce jour, malgré nos demandes, aucune nouvelle attestation d'assurance n'a été produite.\n\nCompte tenu de cette situation j'ai demandé ce jour au Commissaire de Justice de délivrer un :\n\nCommandement de justifier d'une assurance contre les risques locatifs visant la clause résolutoire.\n\n Le locataire disposera alors d'un délai légal d'un mois pour produire une attestation d'assurance valide.\n\nÀ défaut de régularisation dans ce délai, nous disposerons d'un second fondement de résiliation du bail, indépendant des impayés.\n\n3. Situation aggravante\n Le logement a récemment été touché par un incendie alors que le locataire ne disposait plus d'une assurance habitation en cours de validité.\n\nCet élément sera porté à la connaissance de l'avocat et du juge afin d'étayer le dossier, sans pour autant dispenser du respect de la procédure légale relative au défaut d'assurance.\n\n4. Prochaine étape avec l'avocat\n À compter du 18 août 2026, si les impayés n'ont pas été intégralement régularisés, le dossier sera transmis à notre avocat afin de délivrer une assignation devant le Juge des contentieux de la protection.\n\nL'objectif sera de solliciter :\n\nla constatation de l'acquisition de la clause résolutoire pour les impayés de loyers ;\nsubsidiairement ou cumulativement, la constatation de l'acquisition de la clause résolutoire pour défaut d'assurance (si le délai d'un mois du second commandement est également expiré) ;\nl'expulsion du locataire ;\nla condamnation au paiement des sommes restant dues ainsi qu'aux dépens."}, {"post": 5434170357, "contenu": "Ordre de mission UDI Gestion - Sinistre au 31 rue du Général de Gaulle - 91610 Ballancourt / Essonne\n\n            Ordre de Mission - UDI Gestion                Ordre de Mission\n Bonjour,\n\nSuite à un sinistre déclaré, nous vous mandatons par la présente pour effectuer les travaux de remise en état nécessaires dans le bien que nous gérons.\n\n Détails de l'intervention\n Nature du sinistre : remplacement porte d'entrée\n\nNature du bien : Appartement\n\nAdresse du bien : 31 rue du Général de Gaulle - 91610 Ballancourt / Essonne\n\nMoyen d'accès : Contacter locataire\n\n  Référence à rappeler\n Merci d'indiquer impérativement la référence suivante sur tous vos devis et factures :\n\nROUCHE Bernard et Véronique / UDI GESTION - 2 rue Charles Drezet 91100 Corbeil-Essonnes. Adresse d'intervention: 31 rue du Général de Gaulle - 91610 Ballancourt / Essonne\n\n  Contact Locataire\n Nom : Emmanuelle ROUSSELET\n\nAdresse : 31 rue du Général de Gaulle - 91610 Ballancourt / Essonne\n\nTéléphone : 33614102310\n\n Nous vous remercions de bien vouloir prendre contact avec le locataire pour convenir d'un rendez-vous et de nous transmettre votre devis dans les plus brefs délais.\n\nVeuillez également nous accuser réception de cet ordre de mission.\n\nCordialement,\n\nL'équipe UDI Gestion\n\n    UDI Gestion\n                SAS au capital de 1000 € - RCS: EVRY n° 907 631 170\n                Siège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\n                N° TVA Intra-communautaire: FR23907631170\n                Carte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\n                Numéro Orias n° 23006870\n\n                Assurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\n                Garantie financière: QBE Insurance (400 000 €)\n                Médiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr   \n Vos données personnelles (RGPD) — Les données que vous nous communiquez (par email ou via nos portails partenaires : Leboncoin, SeLoger…) sont traitées par Patrimoine Gestion Vedrines (agence UDI Corbeil-Essonnes) pour gérer vos demandes et transactions. Elles sont conservées selon les durées légales et réservées à notre personnel habilité. Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation et d'opposition, à exercer auprès de nvedrines@udi-immo.com. Pour en savoir plus ou introduire une réclamation auprès de la CNIL, consultez notre politique de confidentialité : https://udi-immo.com/donnees-personnelles/"}, {"post": 5434168679, "contenu": "Ordre de mission UDI Gestion - Sinistre au 31 rue du Général de Gaulle - 91610 Ballancourt / Essonne\n\n            Ordre de Mission - UDI Gestion                Ordre de Mission\n Bonjour,\n\nSuite à un sinistre déclaré, nous vous mandatons par la présente pour effectuer les travaux de remise en état nécessaires dans le bien que nous gérons.\n\n Détails de l'intervention\n Nature du sinistre : remplacement porte d'entrée\n\nNature du bien : Appartement\n\nAdresse du bien : 31 rue du Général de Gaulle - 91610 Ballancourt / Essonne\n\nMoyen d'accès : Contacter locataire\n\n  Référence à rappeler\n Merci d'indiquer impérativement la référence suivante sur tous vos devis et factures :\n\nROUCHE Bernard et Véronique / UDI GESTION - 2 rue Charles Drezet 91100 Corbeil-Essonnes. Adresse d'intervention: 31 rue du Général de Gaulle - 91610 Ballancourt / Essonne\n\n  Contact Locataire\n Nom : Emmanuelle ROUSSELET\n\nAdresse : 31 rue du Général de Gaulle - 91610 Ballancourt / Essonne\n\nTéléphone : 33614102310\n\n Nous vous remercions de bien vouloir prendre contact avec le locataire pour convenir d'un rendez-vous et de nous transmettre votre devis dans les plus brefs délais.\n\nVeuillez également nous accuser réception de cet ordre de mission.\n\nCordialement,\n\nL'équipe UDI Gestion\n\n    UDI Gestion\n                SAS au capital de 1000 € - RCS: EVRY n° 907 631 170\n                Siège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\n                N° TVA Intra-communautaire: FR23907631170\n                Carte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\n                Numéro Orias n° 23006870\n\n                Assurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\n                Garantie financière: QBE Insurance (400 000 €)\n                Médiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr   \n Vos données personnelles (RGPD) — Les données que vous nous communiquez (par email ou via nos portails partenaires : Leboncoin, SeLoger…) sont traitées par Patrimoine Gestion Vedrines (agence UDI Corbeil-Essonnes) pour gérer vos demandes et transactions. Elles sont conservées selon les durées légales et réservées à notre personnel habilité. Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation et d'opposition, à exercer auprès de nvedrines@udi-immo.com. Pour en savoir plus ou introduire une réclamation auprès de la CNIL, consultez notre politique de confidentialité : https://udi-immo.com/donnees-personnelles/"}, {"post": 4524118424, "contenu": "0031 _ SDC 31 BD JEAN JAURES 94300 SAINT OUEN _  Dégât des eaux – demande de mise en relation avec le copropriétaire concerné – 31 Boulevard Jean Jaurès, 93400 Saint-Ouen-sur-Seine\n\nMadame, Monsieur, bonjour, \n \nSyndic de la copropriété citée en objet, nous sommes informés d’un dégât des eaux. La fuite proviendrait de l’appartement de M et MME RIQUIER, lot 111 au 3ème étage face du bâtiment B qui endommage l’appartement du 2ème étage face lot 108, géré par UDI qui nous lit en copie. \n \nNous vous demandons de mandater un plombier dans les meilleurs délais pour l’appartement lot 111 car le locataire ne veut pas le faire.\n \nComptant sur vous, \n \nBien cordialement,   \n \nLE SYNDIC  \n \nIsabelle GEORGE \nCollaboratrice de M. JEANDIN \n \n\n11, rue Jeanne d’Arc  75013 PARIS\nAccueil téléphonique et physique sur rendez-vous uniquement : \nDu lundi au vendredi 10h-12h  -  14h-17h\nTél bureau : 01 45 81 02 54\nTél comptabilité : 07 88 50 91 13 \n \nCourriel standard       : contact (at)jeandin-immobilier.com\nCourrier comptabilité :  comptabilite (at)jeandin-immobilier.com \n \nwww.jeandin-immobilier.com\n \n\n  \nDe : UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com> \nEnvoyé : vendredi 26 septembre 2025 11:57\nÀ : contact@jeandin-immobilier.com; udi-immo_pulse_18040759682_71d74b1a06e4184ad9e0__66471427@use1.mx.monday.com\nObjet : Dégât des eaux – demande de mise en relation avec le copropriétaire concerné – 31 Boulevard Jean Jaurès, 93400 Saint-Ouen-sur-Seine\n\n Madame, Monsieur,\n\nEn ma qualité de gestionnaire de la SCI SBMI, propriétaire d’un logement sis 31 Boulevard Jean Jaurès, 93400 Saint-Ouen-sur-Seine, je me permets de vous solliciter concernant un dégât des eaux survenu depuis hier dans l’appartement que nous gérons.\n\nNos locataires subissent en effet des infiltrations d’eau provenant du logement situé à l’étage supérieur. Comme nous ne gérons pas ce bien et que nous ne connaissons pas le copropriétaire concerné, nous vous remercions de bien vouloir transmettre cette information à celui-ci.\n\nNos locataires ont d’ores et déjà déclaré le sinistre auprès de leur assurance. Vous trouverez ci-joint la copie du courrier de déclaration de sinistre, lequel précise expressément la nécessité que les occupants de l’appartement du dessus procèdent à une recherche de fuite afin de permettre la réparation rapide et la prise en charge par les assurances.\n\nNous vous serions reconnaissants de bien vouloir :\n\ninformer le copropriétaire concerné de la situation,\nnous tenir informés des démarches entreprises afin que la fuite soit réparée dans les meilleurs délais.\nDans l’attente de votre retour, nous vous remercions pour votre diligence et restons à votre disposition pour toute précision complémentaire.\n\nVeuillez agréer, Madame, Monsieur, l’expression de nos salutations distinguées.\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30"}, {"post": 4523884572, "contenu": "0031 TR: TR: URGENT Dégât des eaux – demande de mise en relation avec le copropriétaire concerné – 31 Boulevard Jean Jaurès, 93400 Saint-Ouen-sur-Seine\n\nMadame, bonjour, \n \nNous avons fais suivre votre mail aux propriétaires : M. ou MME RIQUIER qui résident 1 RUE JOACHIM DU BELLAY DOMAINE DE MARSINVAL 78540 VERNOUILLET. \n \nNous vous invitons à leur adresser un courrier si nécessaire. \n \nBien cordialement,  \n \nLE SYNDIC  \n \nIsabelle GEORGE \nCollaboratrice de M. JEANDIN \n \n\n11, rue Jeanne d’Arc  75013 PARIS\nAccueil téléphonique et physique sur rendez-vous uniquement : \nDu lundi au vendredi 10h-12h  -  14h-17h\nTél bureau : 01 45 81 02 54\nTél comptabilité : 07 88 50 91 13 \n \nCourriel standard       : contact (at)jeandin-immobilier.com\nCourrier comptabilité :  comptabilite (at)jeandin-immobilier.com \n \nwww.jeandin-immobilier.com\n \n\n \n \nDe : contact@jeandin-immobilier.com <contact@jeandin-immobilier.com> \nEnvoyé : vendredi 26 septembre 2025 12:38\nÀ : \nObjet : 0031 TR: URGENT Dégât des eaux – demande de mise en relation avec le copropriétaire concerné – 31 Boulevard Jean Jaurès, 93400 Saint-Ouen-sur-Seine\nImportance : Haute\n\n Madame, bonjour, \n \nNous vous faisons suivre le mail reçu ci-dessous de la gestionnaire locative de l’appartement, lot 108, situé en dessous de votre appartement (lot 111) pour vous demander de prendre contact avec votre locataire afin qu’il mandate un plombier pour une recherche de fuite dans le cadre de la convention IRSI. \n \nComptant sur votre action rapide, \n \nVous en souhaitant bonne réception,  \n \nLE SYNDIC  \n \nIsabelle GEORGE \nCollaboratrice de M. JEANDIN \n \n\n11, rue Jeanne d’Arc  75013 PARIS\nAccueil téléphonique et physique sur rendez-vous uniquement : \nDu lundi au vendredi 10h-12h  -  14h-17h\nTél bureau : 01 45 81 02 54\nTél comptabilité : 07 88 50 91 13 \n \nCourriel standard       : contact (at)jeandin-immobilier.com\nCourrier comptabilité :  comptabilite (at)jeandin-immobilier.com \n \nwww.jeandin-immobilier.com\n \n\n  \nDe : UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com> \nEnvoyé : vendredi 26 septembre 2025 11:57\nÀ : contact@jeandin-immobilier.com; udi-immo_pulse_18040759682_71d74b1a06e4184ad9e0__66471427@use1.mx.monday.com\nObjet : Dégât des eaux – demande de mise en relation avec le copropriétaire concerné – 31 Boulevard Jean Jaurès, 93400 Saint-Ouen-sur-Seine\n\n Madame, Monsieur,\n\nEn ma qualité de gestionnaire de la SCI SBMI, propriétaire d’un logement sis 31 Boulevard Jean Jaurès, 93400 Saint-Ouen-sur-Seine, je me permets de vous solliciter concernant un dégât des eaux survenu depuis hier dans l’appartement que nous gérons.\n\nNos locataires subissent en effet des infiltrations d’eau provenant du logement situé à l’étage supérieur. Comme nous ne gérons pas ce bien et que nous ne connaissons pas le copropriétaire concerné, nous vous remercions de bien vouloir transmettre cette information à celui-ci.\n\nNos locataires ont d’ores et déjà déclaré le sinistre auprès de leur assurance. Vous trouverez ci-joint la copie du courrier de déclaration de sinistre, lequel précise expressément la nécessité que les occupants de l’appartement du dessus procèdent à une recherche de fuite afin de permettre la réparation rapide et la prise en charge par les assurances.\n\nNous vous serions reconnaissants de bien vouloir :\n\ninformer le copropriétaire concerné de la situation,\nnous tenir informés des démarches entreprises afin que la fuite soit réparée dans les meilleurs délais.\nDans l’attente de votre retour, nous vous remercions pour votre diligence et restons à votre disposition pour toute précision complémentaire.\n\nVeuillez agréer, Madame, Monsieur, l’expression de nos salutations distinguées.\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30"}, {"post": 4523542425, "contenu": "Je fais le point avec Mme SECOND et l'informe qu'il n'y a pas besoin de prévenir matera car Fanny TRINQUAND (ancienne propriétaire du logement de Mr GALLAND) m'indique que Matera n('est là qu'en tant que conseil.\n\nhttps://mail.google.com/mail/u/0/#sent/DmwnWrRmVpffgZwkDThTrgcWsKpbdxTbwBQXKZcmRVJghfZGVnDvvtLNPfrCqKdzVTXSXHhkgPBL\n\nSuivi sinistre – 4 Place Saint Léonard, 91100 Corbeil-Essonnes (2ème étage – logement de M.\n \n\nBonjour,\n\nJe fais suite à notre échange téléphonique d'hier.\n\nEn tant que gestionnaire du logement appartenant à M. GALLAND, sis 4 Place Saint Léonard – 2ème étage, je vous informe qu’un dégât des eaux a été déclaré par son locataire. Un rendez-vous d’expertise est programmé le 3 octobre et je ne manquerais pas de vous tenir informé.\nLe logement du 1er étage est également impacté, et l’origine semblerait provenir de votre logement, situé au 3ème étage pour lequel vous m'avez informé avoir également effectué une déclaration auprès de votre assurance.\n\nNous avons demandé au locataire du second étage que nous gérons de nous transmettre sa déclaration et de nous tenir informés de ses échanges avec son assurance, l’expert et les éventuels artisans.\n\nJe me suis également entretenu avec Mme TRINQUAND votre prédécesseur dans la copropriété qui m'informe que Matera n'est là qu'en tant que conseil et que c'est à ce jour vous le syndic et vous qui devez informer l'assurance de la copropriété.\n\nJe vous laisse donc les informer et me tenir au courant.\n\nDans ce dossier je vous donne les coordonnées des différents interlocuteurs si vous en avez besoin et je reste disponible:\n\n- locataire premier étage 07 53 22 23 53\n\n- Propriétaire premier étage  06 65 95 28 61\n\n- locataire 2ème étage : Me contacter au 07 45 23 43 98\n\n- Nouveau propriétaire Mr GALLAND 06 61 84 87 27\n\n- 3ème étage locataire en place  Iman TLAMAZI 07 53 10 91 52\n\nBien cordialement.\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30"}, {"post": 4826139720, "contenu": "je leur répond car je ne comprends pas bien copie bailleur:\n\nhttps://mail.google.com/mail/u/0/#sent/lLtBPchXHThFgfCLTRcGndPWgTQZDfNpDlCdssXkQLqqClXwfrjLgvnfWPvGGZSKDSZJkzTg\n\nBonjour,\n\nNous accusons bonne réception de votre courriel et vous remercions pour les précisions apportées.\n\nNous vous confirmons vous répondre en notre qualité de gestionnaire du logement concerné, les propriétaires étant en copie du présent échange.\n\nSi nous comprenons bien votre message, vos services sont dans l’attente de devis de remise en état du logement situé au 2ᵉ étage afin de déterminer s’il y a lieu, ou non, de mandater un expert, ce mandat n’étant envisagé qu’au-delà d’un montant de dommages estimé à 1 600 €.\n\nToutefois, nous souhaitons attirer votre attention sur un point qui suscite une réelle inquiétude de notre part et de celle des propriétaires. En effet, l’effondrement partiel du plafond laisse craindre une possible atteinte à la structure du logement (plafond, support, voire plancher), au-delà des seules finitions visibles.\n\nÀ ce stade, l’absence de mandat d’expertise ne permet pas, selon nous, de vérifier de manière contradictoire et objective le bon état structurel du bien. Nous précisons par ailleurs que la fuite provenant du logement situé au-dessus n’a été réparée que la semaine dernière, alors même qu’elle perdurait depuis un certain temps. Les occupants concernés n’ont pas toujours fait preuve de la vigilance nécessaire, ce qui renforce nos craintes quant à la durée d’exposition du bâti à l’humidité.\n\nDans ce contexte, la production de simples devis de remise en état esthétique (plafonds, peintures) nous paraît insuffisante pour garantir que l’ensemble des désordres, notamment structurels, aient été correctement identifiés et pris en compte.\n\nNous restons bien entendu à votre disposition pour échanger sur ce point et vous remercions par avance de bien vouloir nous préciser la position de l’assureur quant à l’opportunité d’une expertise, au regard de ces éléments.\n\nDans l’attente de votre retour, nous vous prions d’agréer, Madame, Monsieur, l’expression de nos salutations distinguées.\n\nCordialement."}, {"post": 4627262472, "contenu": "je demande à la société qui a remplacée le termostat de me renseigner\n\nhttps://mail.google.com/mail/u/0/#sent/lLtBPcgjlLnSPggzvPqnbJgcDXTnncQHcgfNTncDgCLqGNJlQJknShfdJgJvvKdlfbzjBGCN\n\nBonjour,\nje reviens vers vous concernant votre intervention de remplacement de thermostat dans le logement de Mr IVANCIC occupé par Mr JOEL MARTIN au 2 PLACE MARECHAL FOCH HÔTEL D'AUX Bât.B Pte.04 44000 NANTES.\nvoici ceux que les locataires m'expliquent:\nVoici les tuyaux de chauffage pour les 3 appartements à leur étage :\n\n \n\nSur chacun des 3 tuyaux qui alimentent les 3 appartements, il y a une vanne à bille électronique (spécification en pièce jointe) :\n\n \n\nChaque vanne est connectée au thermostat de l’appartement correspondant. Lorsque la température dans un appartement est inférieure à la température de consigne du thermostat, celui-ci envoie un signal pour ouvrir la vanne, permettant ainsi à l’eau chaude de circuler dans les radiateurs de l’appartement. Une fois que la température de l’appartement atteint la consigne, le thermostat envoie un signal pour fermer la vanne.\n\nLeur problème est que ce mécanisme — qui fonctionnait avant le remplacement de leur thermostat — ne fonctionne plus. Que leur appartement soit plus chaud ou plus froid que la température réglée ne change rien : la vanne reste ouverte en permanence, et l’eau chaude circule constamment dans nos radiateurs. Ils ont testé en réglant leur thermostat à une température très basse pendant plusieurs jours, le thermostat indiquait qu’il n’envoyait aucun signal à la vanne, et pourtant nos radiateurs continuaient malgré tout de recevoir de l’eau chaude.\n\nJe ne sais pas si le problème vient du nouveau thermostat (défectueux), d’un mauvais câblage, ou d’un dysfonctionnement de la vanne. Mais tant que ce n’est pas corrigé, ils sont obligés de régler la chaleur de leur appartement en ajustant manuellement les vannes de chaque radiateur.\nJe serais ravie de pouvoir échanger avec vous afin de savoir si il y a bien un dysfonctionnement ou si ils n'utilise pas le système de chauffage correctement.\nBien cordialement"}, {"post": 4627259784, "contenu": "les locataires ont un problèmes de chauffage\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbmrKGXNfdqbrNlSpPPTQBZLxFzPBtjBrTCpbQMPWPQZJqqJFLTRlPzsrFqrWMkVXQ\n\nBonjour Marion,\n\nJe suis d’accord avec tout ce que vous avez dit.\n\nVoici les tuyaux de chauffage pour les 3 appartements de notre étage :\n\n \n\nSur chacun des 3 tuyaux qui alimentent les 3 appartements, il y a une vanne à bille électronique (spécification en pièce jointe) :\n\n \n\nChaque vanne est connectée au thermostat de l’appartement correspondant. Lorsque la température dans un appartement est inférieure à la température de consigne du thermostat, celui-ci envoie un signal pour ouvrir la vanne, permettant ainsi à l’eau chaude de circuler dans les radiateurs de l’appartement. Une fois que la température de l’appartement atteint la consigne, le thermostat envoie un signal pour fermer la vanne.\n\nNotre problème est que ce mécanisme — qui fonctionnait avant le remplacement de notre thermostat — ne fonctionne plus. Que notre appartement soit plus chaud ou plus froid que la température réglée ne change rien : la vanne reste ouverte en permanence, et l’eau chaude circule constamment dans nos radiateurs.  Nous l’avons prouvé en réglant notre thermostat à une température très basse pendant plusieurs jours, le thermostat indiquait qu’il n’envoyait aucun signal à la vanne, et pourtant nos radiateurs continuaient malgré tout de recevoir de l’eau chaude.\n\nJe ne sais pas si le problème vient du nouveau thermostat (défectueux), d’un mauvais câblage, ou d’un dysfonctionnement de la vanne. Mais tant que ce n’est pas corrigé, nous sommes obligés de régler la chaleur de notre appartement en ajustant manuellement les vannes de chaque radiateur.\n\nN’hésitez pas à me dire si quelque chose n’est pas clair. Un technicien devrait venir analyser et corriger notre problème.\n\nBien cordialement,\nMartin JOEL\n\nOn 10/29/2025 11:35, UDI - Votre Gestionnaire wrote:\n\nBonjour, s'agissant d'un chauffage collectif vous ne pouvez pas réellement contrôler le réglage.\nEn effet:Dans un chauffage collectif, le fonctionnement global des radiateurs est géré par une chaudière commune et un réseau de distribution d’eau chaude. Cela signifie que vous ne contrôlez pas directement la production de chaleur, seulement la quantité de chaleur qui entre dans votre radiateur. Voici comment ça fonctionne :\n\nThermostat de radiateur (ou vanne thermostatique)\n\nCette vanne ajuste la quantité d’eau chaude qui circule dans votre radiateur.\nSi vous la baissez, votre radiateur recevra moins d’eau chaude et donc votre pièce sera moins chauffée.\nSi vous la montez, le radiateur recevra plus d’eau chaude, mais la température maximale dépendra de l’eau fournie par le réseau collectif.\n\nLimites dans un chauffage collectifVous ne pouvez pas faire descendre la température de l’eau du réseau, qui est réglée par le gestionnaire du chauffage collectif.\nSi tout le monde ouvre son thermostat à fond, la température de votre radiateur peut quand même être limitée par la pression et la température de l’eau dans le réseau.\nCertaines installations collectives utilisent un système où le débit est déjà régulé pour chaque appartement, ce qui limite encore l’effet individuel de votre thermostat.\n\nEn espérant avoir répondu à votre demande.\nCordialement"}, {"post": 4696866682, "contenu": "je répond au locataire\n\nhttps://mail.google.com/mail/u/0/#sent/lLtBPchKqSnfMqSpSzdxqtPfFdDVnhfxXwXlcqldKdwxWTHwrZkWWNpLKnrtVJPRtrzfwGzl\n\nBonjour,\n\nMerci pour votre retour.\n\nConcernant la présence de nuisibles (suspicion de rongeurs), j’ai contacté le syndic et suis actuellement en attente de leur réponse.\n\nPour la VMC de la pièce principale, elle fonctionne grâce à un interrupteur indépendant situé à côté de votre évier. Je l’ai moi-même testée ce matin : elle n’est pas liée à l’éclairage, contrairement à celle de la salle de bains. Il est important de la laisser fonctionner non seulement lorsque vous êtes présent, mais également en votre absence. Son impact sur la consommation électrique est très faible, et elle est essentielle pour assurer une bonne ventilation du logement.\n\nConcernant la VMC de la salle d’eau, elle est effectivement reliée à la lumière, mais elle est aussi hygroréglable : en cas d’humidité liée à la douche, elle continue de fonctionner un certain temps même lorsque la lumière est éteinte. C’est ce dispositif que nous avons fait réparer au printemps. Si cela ne fonctionne plus, il aurait été nécessaire de m’en informer.\n\nDe mon côté, j’attends désormais le retour des propriétaires pour l’installation de grilles de ventilation sur les fenêtres. \n\nAu sujet du logement en lui-même, celui-ci a été entièrement rénové récemment par le propriétaire, comprenant notamment les équipements, les revêtements, et les installations techniques. Après ces travaux complets, seules des interventions légères ou ponctuelles peuvent encore être envisagées.\nEn l’état, le propriétaire ne pourra pas aller au-delà de l’installation de grilles de ventilation sur les fenêtres, point sur lequel j’attends d’ailleurs leur retour.\n\nPour toute amélioration supplémentaire, notamment en matière d’isolation thermique ou phonique, cela relève exclusivement de la copropriété. Ces éléments ne font pas partie du périmètre sur lequel le propriétaire peut intervenir directement, car ils concernent les parties communes et nécessitent une décision collective.\n\nBien cordialement."}, {"post": 4696809344, "contenu": "reponse du locataire\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbmtMMGcHMMgSmSNdDMWLpbZHzzCrVkrhWsbFNZwBdSWwBGMfHGkgHCmZpvkRCCMVl\n\nMadame, \n\n1. Présence de nuisibles : \n \nTrès bien ! J'ai effectivement prit connaissance, ce week-end, de la venue de cette société spécialisée à laquelle mon frère assurera l'accès à mon logement comme aujourd'hui. En revanche, leur prestation ne s'arrête, si je ne fais pas d'erreur, qu'à une recherche de termites et une désinsectisation. Étant persuadé que je fais face à des rongeurs et non des cafards ou autres nuisibles de ce genre, j'aimerais, s'il vous plaît savoir, s'il vous plaît, vers qui je dois me retourner pour avoir contact avec le syndic... même si je pense devoir avoir recours au conseil syndical ? \n______________________________________________________________________________________________________________________________________________\n\n2. Problématique d’humidité : \n Pour ce problème, je pense ne rien à voir à rajouter si ce n'est que j'attends votre retour et la réponse de mon propriétaire. D'ailleurs, erreur de ma part, mais j'ai oublié de vous faire constater une infiltration d'eau par la vitre de ma salle de bain. En effet, quand je prends ma douche, il arrive parfois que de l'eau passe de cette vitre et inonde mon carrelage. \n______________________________________________________________________________________________________________________________________________\n\n3. Fonctionnement des VMC : \n VMC de la pièce de vie :\n Pour la VMC de la pièce de vie, je tiens à vous confirmer qu'elle est automatiquement allumée lorsque je suis présent dans le logement. Mais étant donné qu'elle fonctionne avec la lumière, vous comprendrez qu'elle n'est pas active lorsque je dors ou bien quand je suis absent. Cela se résumerait à allumer ma lumière inutilement et impacter mes factures d'électricité.  \n\nVMC de la salle d’eau : \n Pour cette VMC, elle est allumée dès le moment où je vais me laver, jusqu'au moment de me coucher (à savoir que de manière générale, je laisse s'écouler une heure pour que la VMC puisse agir correctement), et que ma porte de la salle de bain reste toujours ouverte, présent ou non dans le studio. Or, elle n'a pas l'air de fonctionner correctement, c'est-à-dire que le \"premier moteur\" comme me l'aviez expliqué, tourne continuellement mais le deuxième tourne que lorsque ma lumière est allumée. Je pense donc que ce n'est pas suffisant comme en témoigne le taux d'humidité et les photos de l'appartement. Enfin, vous comprendrez également que la lumière de ma salle de bain n'est pas allumée hormis lors des situations présentées au début de ce même paragraphe. Comme pour la VMC de vie, cela se résumerait à allumer ma lumière inutilement et impacter mes factures d'électricité. \n______________________________________________________________________________________________________________________________________________\n\n4. Suite des actions : \n - Je vous confirme que la VMC ne fonctionne pas comme indiqué dans votre mail et comme vous l'aviez expliqué lors de l'intervention en printemps dernier. -  Je vous retourne à ce paragraphe : Pour la VMC de la pièce de vie, je tiens à vous confirmer qu'elle est automatiquement allumée lorsque je suis présent dans le logement. Mais étant donné qu'elle fonctionne avec la lumière, vous comprendrez qu'elle n'est pas active lorsque je dors ou bien quand je suis absent. Cela se résumerait à allumer ma lumière inutilement et impacter mes factures d'électricité.  - Comme pour aujourd'hui, mon frère assurera les accès à mon logement le mardi 2 décembre prochain. \nPour la suite des évènements, j'attends votre retour, espérant que les choses ne traînent pas... \nJe vous souhaite une excellente soirée et plein de courage pour cette semaine. \nBien à vous, \nWesley DARRAS."}, {"post": 4696016912, "contenu": "je fais un résumé aux bailleurs et leur demande l'installation de grille de ventilation sur les fenêtres\n\nhttps://mail.google.com/mail/u/0/#sent/CllgCJNtdmCHvJqkQTGXTqPTXFvkDKFFlhRqQWvtkrxRXfDSwDDRRJmZWTptMKNQqNnfJQNJwBq\n\nMadame, Monsieur,\n\nSuite à ma visite d’aujourd’hui dans le logement de votre locataire, je vous informe des constats suivants :\n\nPrésence importante de condensation dans plusieurs zones du logement : fenêtres (PVC double vitrage), porte d’entrée, intérieur d’un placard, coin de mur entre la cuisine et la salle d’eau, ainsi que dans la salle d’eau.\nAbsence de grilles de ventilation sur les fenêtres, limitant la ventilation naturelle du logement.\nConcernant la VMC de la pièce principale, celle-ci était coupée lors de mon passage. Elle est pourtant équipée d’un interrupteur dédié situé à gauche de la porte de la salle d’eau et doit impérativement rester en fonctionnement de manière continue.\nEn effet, cette VMC assure l’extraction de l’air vicié et permet au logement de bénéficier d’un renouvellement d’air constant. Lorsque cette VMC est désactivée, l’humidité stagne dans l’air intérieur, entraînant rapidement l’apparition de condensation, notamment sur les parois froides comme les fenêtres ou les portes. J’ai donc rappelé au locataire qu’il ne devait en aucun cas l’éteindre.\nLa VMC de la salle d’eau, réparée au printemps, doit continuer de fonctionner automatiquement (mode hygrométrique) même lorsque la lumière est éteinte, si le taux d’humidité reste élevé après une douche. Je suis en attente d’une confirmation du locataire concernant son bon fonctionnement.\n Par ailleurs, dans les parties communes, j’ai constaté une note du syndic indiquant qu’une société interviendra le 2 décembre à partir de 8h30 pour le traitement des nuisibles. J’ai rappelé au locataire qu’il devra être présent ou donner accès à son logement le jour de l’intervention.\n\nAfin d’améliorer durablement la ventilation et de limiter les phénomènes de condensation, il apparaît nécessaire d’installer des grilles de ventilation sur les fenêtres.\n\nPouvez-vous m’indiquer si vous souhaitez :\n\nfaire intervenir votre propre artisan,\nou\nque je mandate l’un de nos partenaires pour procéder à cette installation ?\n Je reste à votre disposition pour tout complément d’information et vous remercie pour votre retour.\n\nCordialement."}, {"post": 4695975048, "contenu": "compte rendu au locataire\n\nhttps://mail.google.com/mail/u/0/#sent/lLtBPchKqSnfMqSpSzdxqtPfFdDVnhfxXwXlcqldKdwxRjTvgWsLWdFcgTwkgZVWvTXPWwQb\n\nMonsieur,\n\nSuite à ma visite de ce jour dans votre logement, je souhaite vous faire un compte rendu des constats réalisés ainsi que des actions à mettre en œuvre.\n\n1. Présence de nuisibles\n Vous m’avez signalé la présence de nuisibles dans l’immeuble. Après vérification, je vous confirme que la gestion de ce problème relève du syndic de copropriété.\n\nJ’ai pu constater qu’une note d’information a été affichée dans les parties communes, indiquant l’intervention d’une société spécialisée le 2 décembre 2025 à partir de 8h30.\nJe vous remercie de bien vouloir vous organiser pour permettre l’accès à votre logement lors de cette intervention, afin que le traitement soit pleinement efficace.\n\n2. Problématique d’humidité\n Lors de ma visite, j’ai constaté les éléments suivants :\n\nPrésence de condensation sur les fenêtres (PVC double vitrage) et la porte d’entrée ;\nCondensation dans l’intérieur d’un meuble de placard ;\nTraces d’humidité dans le coin de mur entre la cuisine et la salle d’eau, ainsi que dans la salle d’eau elle-même ;\nAbsence de grilles de ventilation sur les fenêtres.\n Je vais demander aux propriétaires de faire installer des grilles de ventilation, ce qui permettra d’améliorer la ventilation naturelle du logement. Je reviendrai vers vous dès que j’aurai leur retour.\n\n3. Fonctionnement des VMC\n VMC de la pièce de vie\n J’ai constaté que la VMC située dans la pièce principale, commandée par l’interrupteur placé à gauche de la porte de la salle d’eau, était éteinte.\nOr, cette VMC doit fonctionner en continu, elle à été installée à la rénovation totale du logement. Elle assure la circulation et le renouvellement permanent de l’air dans le logement, ce qui permet de limiter l’humidité, les moisissures et la condensation.\n\nJe vous rappelle qu’il est indispensable de ne pas couper cette VMC.\n\nVMC de la salle d’eau\n La VMC de la salle d’eau, commandée par l’allumage de la lumière, est également hygrométrique : elle doit continuer à fonctionner même lorsque la lumière est éteinte, tant que le taux d’humidité reste élevé (notamment après une douche).\n\nNous sommes intervenus au printemps pour la réparer.\nJe vous remercie de bien vouloir me confirmer qu’elle fonctionne toujours dans ces conditions.\n\nPar ailleurs, après utilisation de la douche, il serait souhaitable de laisser la porte de la salle d’eau ouverte afin que la VMC de la pièce principale contribue également à la bonne circulation de l’air.\n\n4. Suite des actions\n Je vous remercie de bien vouloir :\n\nme confirmer que la VMC de la salle d’eau fonctionne bien après une douche même lorsque la lumière est éteinte ;\nLaisser la VMC de la pièce principale en fonction continuellement\nEtre présent ou donner accès au logement pour l'intervention de la société en charge des nuisibles.\n Je reviendrai vers vous dès que j’aurai le retour des propriétaires concernant l’installation des grilles de ventilation sur les fenêtres.\n\nRestant à votre disposition pour toute question,\n\nVeuillez agréer, Madame, Monsieur, l’expression de mes salutations distinguées."}, {"post": 4686712661, "contenu": "le locataires m'informe de plusieurs problématiques:\n\n- moisissures\n\n- fissures\n\n-rongeurs\n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbmtMMGcHMMgSmSNdDMWLpbZHzzCrVkrhWsbFNZwBdSWXBGXcvHljZVDVqKKBFFjkg\n\nBonjour Mme.Brenot,\nJ'espère que vous vous portez bien ? \nJe viens à vous aujourd'hui pour vous faire part de multiples problèmes concernant mon studio situé au 13 Rue du 14 Juillet, 91100, Corbeil-Essonnes. \nPremièrement, je vous adresse ci-joint, des photos ou vous y verrez des traces de moisissures et des fissures au niveau du bas des murs. \nConcernant les fissures, je pense qu'elles sont principalement dûes à la présence de rongeurs (au vu du bruit je dirais des rats) qui grattent fortement les murs. Les fissures sont présentes derrière la porte de ma salle bain et dans la salle de bain directement et j'ai bien peur qu'à terme, il puisse rentrer chez moi. Il faudrait, s'il vous plaît, faire intervenir un prestataire pour authentifier les faits et surtout pour faire en sorte que ces mêmes rats disparaissent de mes murs. \nPour le reste, ce sont des traces de moisissures qui persistent et réapparaissent avec le froid et surtout avec les temps de pluies qui reviennent de façon récurrentes... En effet, lorsque le temps est bon, ensoleillé et doux, je n'ai zéro problème (à part dans la salle de bain). Mais lorsque la pluie reprend et que l'humidité est présente, mon studio est sujet à de gros problèmes de moisissures qui s'étendent sur l'entièreté du logement. \nPourtant ce n'est pas faute d'aérer... En effet, dès lors que je quitte mon logement, je fais en sorte d'ouvrir les fenêtres pour que l'appartement puisse respirer au maximum. C'est à dire qu'en général, c'est ouvert de 6h30 jusqu'à minimum 20h00. J'avoue moins aérer lorsque je suis présent car difficile de vivre les fenêtres ouvertes quand il fait des températures en dessous de 10°. \nJ'aimerais savoir ce qu'il est possible de faire pour pallier à ses problèmes qui peuvent porter atteinte à ma santé physique et dans un second temps à ma santé mentale... Car en effet vivre dans un logement insalubre qui n'est même pas dû à mon hygiène de vie, mais à mon activité, cela pèse, à terme, sur le moral. \nJe vous laisse donc avec cet écrit et les photos pour revenir vers moi, et vous remercie par avance de l'attention portée à mon message.\nBien à vous, \n\nMoisissures _ Humidité.pdf"}, {"post": 4509287734, "contenu": "RIB et état des lieux\n \n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30\n\n---------- Forwarded message ---------\nDe : lucie fernandes <fernandeslucie01@gmail.com>\nDate: ven. 19 sept. 2025 à 10:12\nSubject: Re: RIB et état des lieux\nTo:  <votregestionnaire@udi-immo.com>\n\nBonjour,\n\nMerci pour ce retour sur les divers points soulevés.\n\nC'est ok pour nous pour faire déduire un nettoyage et faire passer quelqu'un pour remettre une vis de fixation sur le radiateur.\n\nBien à vous.\n\nLucie Fernandes\n\nLe jeu. 18 sept. 2025 à 17:15, UDI - Votre Gestionnaire <votregestionnaire@udi-immo.com> a écrit :\n\nBonjour Madame Fernandes,\n\nNous avons bien pris en compte vos interrogations concernant l'état des lieux de sortie.\n\nConcernant les traces multiples constatées à l'intérieur du logement, notamment les traces de calcaire, celles-ci n'étaient pas présentes lors de l'état des lieux d'entrée. Compte tenu de la durée d'occupation, nous estimons que ces traces sont anormales et nécessitent une intervention professionnelle. Nous avons donc fait appel à une entreprise de nettoyage pour remettre en état le logement.\n\nS'agissant du radiateur de la salle de bain, nous avons effectivement constaté sur les photos de l'état des lieux d'entrée que le problème de fixation et l'absence des caches-vis existaient déjà. L'origine de ce problème date de l'occupation par la gendarmerie. Cependant, comme l'état des lieux avait été réalisé selon leur protocole et sans photos détaillées à l'époque, ce point n'avait pas été expressément relevé.\n\nEn ce qui concerne l'entretien extérieur, l'état du jardin est conforme à ce qui avait été constaté à l'entrée des locataires, ni plus ni moins. Les haies ne sont pas taillées et la pelouse n'est pas tondue, tout comme à leur arrivée.\n\nEn conséquence, nous prévoyons de retenir le montant de la facture de nettoyage sur la caution des locataires sortants. Nous allons par ailleurs insister auprès des nouveaux locataires sur leurs obligations concernant l'entretien du jardin, notamment la taille des haies au printemps.\n\nNous souhaiterions savoir si vous êtes d'accord avec cette retenue. De plus, nous vous demandons si vous souhaitez que nous fassions intervenir un technicien pour refixer correctement le radiateur, afin d'éviter d'endommager davantage les autres fixations. Concernant les caches-vis, il nous semble difficile d'en retrouver, mais si vous acceptez cette intervention, nous pourrions relever les références et la marque du radiateur pour tenter de les trouver.\n\nCordialement,\n\nMarion BRENOT\n\nUDI GESTION\n\nGestionnaire location\n\n📱 07.45.23.43.98\n\n📧 votregestionnaire@udi-immo.com\n\n📍2 Rue Charles Drezet - 91100 à CORBEIL-ESSONNES\n\nDu lundi au vendredi de 09h30 à 12h00 et de 13h00 à 17h30\n\nLe lun. 15 sept. 2025 à 12:34, lucie fernandes <fernandeslucie01@gmail.com> a écrit :\n\nBonjour,\n\nJe reviens vers vous suite à la réception de l'état des lieux.\n\nA t il été analysé chez vous pour la remise de caution aux locataires sortants ?\n\nJ'ai 3 questions de mon côté...\n\n*L'état semble correct si ce n'est certaines traces qui je pense sont liées à l'utilisation de la maison au quotidien, qu'en pensez vous ?\n\n*Concernant l'entretien extérieur, la pelouse n'est pas tondue (ça a pu repousser...) et les haies non taillées : dans quelle mesure les locataires doivent entretenir l'extérieur ? Si une taille est à faire, aux frais de qui ?\n\n*Sur l'état des lieux, le radiateur de la salle de bain du haut est \"mal fixé et il manque les caches vis à l'avant\" : que s'est il passé ? C'etait déjà notifié sur l'EDL du gendarme ? Quand nous avons livré la maison, c'était bel et bien fixé et les vis non apparentes...\n\nMerci d'avance de votre retour sur ces différents points.\n\nBien à vous.\n\nLucie Fernandes\n\nLe ven. 12 sept. 2025 à 10:21, UDI - Votre comptable <votrecomptable@udi-immo.com> a écrit :\n\nMme Fernandes,\n\nVous trouverez en pj le RIB de l'agence afin d'effectuer le virement de la caution.\n\nJe vous joins également les états des lieux entrée et sortie des derniers locataires.\n\nBonne réception.\n edl entrée.pdf\n edl sortie.pdf\n\nAudrey GUILLON\n\nGestionnaire administrative & comptable\n\n07 63 65 94 32\n\nvotrecomptable@udi-immo.com\n\nUDI GESTION\n\nAbsente le mercredi."}, {"post": 5311516785, "contenu": "Ordre de mission UDI Gestion - Sinistre au 78 rue de Paris, Gretz-Armainvilliers\n\n            Ordre de Mission - UDI Gestion                Ordre de Mission\n Bonjour,\n\nSuite à un sinistre déclaré, nous vous mandatons par la présente pour effectuer les travaux de remise en état nécessaires dans le bien que nous gérons.\n\n Détails de l'intervention\n Nature du sinistre : fuite au toiletts : arrivée d'eau\n\nNature du bien : Appartement\n\nAdresse du bien : 78 rue de Paris, Gretz-Armainvilliers\n\nMoyen d'accès : Contacter locataire\n\n  Référence à rappeler\n Merci d'indiquer impérativement la référence suivante sur tous vos devis et factures :\n\nMECHETY Karim / UDI GESTION - 2 rue Charles Drezet 91100 Corbeil-Essonnes. Adresse d'intervention: 78 rue de Paris, Gretz-Armainvilliers\n\n  Contact Locataire\n Nom : Julien NGUYEN\n\nAdresse : 78 rue de Paris, Gretz-Armainvilliers\n\nTéléphone : 33636875975\n\n Nous vous remercions de bien vouloir prendre contact avec le locataire pour convenir d'un rendez-vous et de nous transmettre votre devis dans les plus brefs délais.\n\nVeuillez également nous accuser réception de cet ordre de mission.\n\nCordialement,\n\nL'équipe UDI Gestion\n\n    UDI Gestion\n                SAS au capital de 1000 € - RCS: EVRY n° 907 631 170\n                Siège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\n                N° TVA Intra-communautaire: FR23907631170\n                Carte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\n                Numéro Orias n° 23006870\n\n                Assurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\n                Garantie financière: QBE Insurance (400 000 €)\n                Médiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr   \n Vos données personnelles (RGPD) — Les données que vous nous communiquez (par email ou via nos portails partenaires : Leboncoin, SeLoger…) sont traitées par Patrimoine Gestion Vedrines (agence UDI Corbeil-Essonnes) pour gérer vos demandes et transactions. Elles sont conservées selon les durées légales et réservées à notre personnel habilité. Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation et d'opposition, à exercer auprès de nvedrines@udi-immo.com. Pour en savoir plus ou introduire une réclamation auprès de la CNIL, consultez notre politique de confidentialité : https://udi-immo.com/donnees-personnelles/"}, {"post": 5402082757, "contenu": "Ordre de mission UDI Gestion - Sinistre au 33 Boulevard Henri Dunant, 91100 Corbeil-Essonnes\n\n            Ordre de Mission - UDI Gestion                Ordre de Mission\n Bonjour,\n\nSuite à un sinistre déclaré, nous vous mandatons par la présente pour effectuer les travaux de remise en état nécessaires dans le bien que nous gérons.\n\n Détails de l'intervention\n Nature du sinistre : panne  d'eau chaude\n\nNature du bien : Appartement\n\nAdresse du bien : 33 Boulevard Henri Dunant, 91100 Corbeil-Essonnes\n\nMoyen d'accès : Contacter locataire\n\n  Référence à rappeler\n Merci d'indiquer impérativement la référence suivante sur tous vos devis et factures :\n\nSAINT FLEUR Christine / UDI GESTION - 2 rue Charles Drezet 91100 Corbeil-Essonnes. Adresse d'intervention: 33 Boulevard Henri Dunant, 91100 Corbeil-Essonnes\n\n  Contact Locataire\n Nom : CRIART (MONGIS) Céline - L78\n\nAdresse : 33 Boulevard Henri Dunant, 91100 Corbeil-Essonnes\n\nTéléphone : 0663477995\n\n Nous vous remercions de bien vouloir prendre contact avec le locataire pour convenir d'un rendez-vous et de nous transmettre votre devis dans les plus brefs délais.\n\nVeuillez également nous accuser réception de cet ordre de mission.\n\nCordialement,\n\nL'équipe UDI Gestion\n\n    UDI Gestion\n                SAS au capital de 1000 € - RCS: EVRY n° 907 631 170\n                Siège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\n                N° TVA Intra-communautaire: FR23907631170\n                Carte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\n                Numéro Orias n° 23006870\n\n                Assurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\n                Garantie financière: QBE Insurance (400 000 €)\n                Médiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr   \n Vos données personnelles (RGPD) — Les données que vous nous communiquez (par email ou via nos portails partenaires : Leboncoin, SeLoger…) sont traitées par Patrimoine Gestion Vedrines (agence UDI Corbeil-Essonnes) pour gérer vos demandes et transactions. Elles sont conservées selon les durées légales et réservées à notre personnel habilité. Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation et d'opposition, à exercer auprès de nvedrines@udi-immo.com. Pour en savoir plus ou introduire une réclamation auprès de la CNIL, consultez notre politique de confidentialité : https://udi-immo.com/donnees-personnelles/"}, {"post": 5401868064, "contenu": "Information Sinistre - Votre bien situé au 33 Boulevard Henri Dunant, 91100 Corbeil-Essonnes\n\n            Information Sinistre - UDI Gestion                Information Sinistre\n Bonjour,\n\nNous vous contactons pour vous informer qu'un sinistre nous a été signalé dans le bien que nous gérons pour votre compte.\n\n Résumé du sinistre\n Nature du bien : Appartement\n\nAdresse du bien : 33 Boulevard Henri Dunant, 91100 Corbeil-Essonnes\n\nNature du sinistre : panne  d'eau chaude\n\nLocataire en place : CRIART (MONGIS) Céline - L78\n\nContact locataire : 0663477995\n\n  Gestion de l'intervention\n Afin de procéder aux investigations nécessaires et d'établir un devis pour les réparations, nous vous remercions de nous indiquer la marche à suivre. Veuillez s'il vous plaît choisir l'une des deux options ci-dessous :\n\n Je mandate UDI Gestion Je gère le sinistre moi-même \n Votre choix nous permettra de lancer la procédure appropriée sans délai.\n\nEn l'absence de retour de votre part, nous nous réservons le droit de mandater une entreprise pour les mesures conservatoires urgentes si la situation l'exige.\n\nCordialement,\n\nL'équipe UDI Gestion\n\n     UDI Gestion\n                SAS au capital de 1000 € - RCS: EVRY n° 907 631 170\n                Siège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\n                N° TVA Intra-communautaire: FR23907631170\n                Carte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\n                Numéro Orias n° 23006870\n\n                Assurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\n                Garantie financière: QBE Insurance (400 000 €)\n                Médiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr   \n Vos données personnelles (RGPD) — Les données que vous nous communiquez (par email ou via nos portails partenaires : Leboncoin, SeLoger…) sont traitées par Patrimoine Gestion Vedrines (agence UDI Corbeil-Essonnes) pour gérer vos demandes et transactions. Elles sont conservées selon les durées légales et réservées à notre personnel habilité. Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation et d'opposition, à exercer auprès de nvedrines@udi-immo.com. Pour en savoir plus ou introduire une réclamation auprès de la CNIL, consultez notre politique de confidentialité : https://udi-immo.com/donnees-personnelles/"}, {"post": 5410850325, "contenu": "Ordre de mission UDI Gestion - Sinistre au 1 Rue des Remparts - 91100 Corbeil Essonnes\n\n            Ordre de Mission - UDI Gestion                Ordre de Mission\n Bonjour,\n\nSuite à un sinistre déclaré, nous vous mandatons par la présente pour effectuer les travaux de remise en état nécessaires dans le bien que nous gérons.\n\n Détails de l'intervention\n Nature du sinistre : reclamation diverse: devis réparation volets\n\nNature du bien : Appartement\n\nAdresse du bien : 1 Rue des Remparts - 91100 Corbeil Essonnes\n\nMoyen d'accès : Contacter locataire\n\n  Référence à rappeler\n Merci d'indiquer impérativement la référence suivante sur tous vos devis et factures :\n\nCHENIKI Mehdi / UDI GESTION - 2 rue Charles Drezet 91100 Corbeil-Essonnes. Adresse d'intervention: 1 Rue des Remparts - 91100 Corbeil Essonnes\n\n  Contact Locataire\n Nom : ALLAOUI Hayat\n\nAdresse : 1 Rue des Remparts - 91100 Corbeil Essonnes\n\nTéléphone : 33601165362\n\n Nous vous remercions de bien vouloir prendre contact avec le locataire pour convenir d'un rendez-vous et de nous transmettre votre devis dans les plus brefs délais.\n\nVeuillez également nous accuser réception de cet ordre de mission.\n\nCordialement,\n\nL'équipe UDI Gestion\n\n    UDI Gestion\n                SAS au capital de 1000 € - RCS: EVRY n° 907 631 170\n                Siège social: 2 rue Charles Drezet 91100 CORBEIL-ESSONNES\n                N° TVA Intra-communautaire: FR23907631170\n                Carte professionnelle Gestion n° CPI 9101 2022 0000000 14 (CCI Evry)\n                Numéro Orias n° 23006870\n\n                Assurance RC Pro: SERENIS ASSURANCES SA n° VD 7.000.001/000408/22528\n                Garantie financière: QBE Insurance (400 000 €)\n                Médiateur à la consommation : MEDIMMOCONSO - contact@medimmoconso.fr   \n Vos données personnelles (RGPD) — Les données que vous nous communiquez (par email ou via nos portails partenaires : Leboncoin, SeLoger…) sont traitées par Patrimoine Gestion Vedrines (agence UDI Corbeil-Essonnes) pour gérer vos demandes et transactions. Elles sont conservées selon les durées légales et réservées à notre personnel habilité. Vous disposez d'un droit d'accès, de rectification, d'effacement, de limitation et d'opposition, à exercer auprès de nvedrines@udi-immo.com. Pour en savoir plus ou introduire une réclamation auprès de la CNIL, consultez notre politique de confidentialité : https://udi-immo.com/donnees-personnelles/"}, {"post": 4662656018, "contenu": "les locataires qui vont bientôt sortir m'informent d'un problème d'humidité. \n\nhttps://mail.google.com/mail/u/0/#inbox/WhctKLbmsLfBkHQThHdbchcqTZltFXtFfDWzVDvTTpMjhWddfngTbNTkBxNVhqXCgpGPPRQ\n\nBonjour madame,\n\nJe me permets de vous contacter pour vous signaler certains problèmes d’humidité dans l’appartement, en amont de notre état des lieux prévu le 24/11.\n\nCet été, nous n’avions pas rencontré de souci particulier, si ce n’est un peu de buée lorsque nous faisions sécher du linge à l’intérieur. En revanche, depuis l’arrivée de l’automne, de la buée se forme désormais en permanence sur les fenêtres, malgré une aération quotidienne et l’utilisation d’un déshumidificateur. Le phénomène persiste même lorsque nous ne faisons pas sécher de linge.\n\nNous avons également constaté que la peinture de la salle de bain a légèrement cloqué, ce qui semble lié à l’humidité ambiante.\n\nJe vous joins quelques photos pour vous montrer la situation actuelle et vous en informer avant l’état des lieux.\n\nMerci par avance pour votre retour et pour les suites que vous pourrez y donner.\n\nBien cordialement,\n\nM. LAMOURE / Mme DA SILVA\n\nJ'en informe le bailleur car cela va poser problème pour le permis de louer pour lequel nous attendons une date de visite\n\nBonjour,\n\nJe me permets de vous informer que les locataires du logement de gauche situé à CORBEIL ESSONNES , dont le départ est prévu prochainement, nous ont signalé l’apparition de problèmes d’humidité dans leur appartement.\n\nSelon leur message, le logement ne présentait pas de souci particulier durant l’été, si ce n’est un peu de buée lors du séchage du linge à l’intérieur. En revanche, depuis l’automne, de la buée se forme désormais en permanence sur les fenêtres, et ce malgré une aération quotidienne et l’utilisation d’un déshumidificateur. Ils précisent également que la peinture de la salle de bain commence à cloquer, vraisemblablement en raison de l’humidité ambiante. Des photos ont été transmises à titre de constat avant l’état des lieux prévu le 24 novembre.\n\nAfin de prévenir l’aggravation de ce phénomène et d’assurer une bonne qualité d’air dans le logement, il serait opportun d’envisager l’installation d’une VMC, comme cela a été fait dans le logement de droite. Cette amélioration contribuerait à éviter la réapparition du problème et pourrait également faciliter l’obtention du permis de louer, pour lequel nous sommes toujours en attente du rendez-vous avec la mairie.\n\nJe reste bien entendu à votre disposition pour tout complément d’information ou pour organiser une visite technique si vous le souhaitez.\n\nBien cordialement.\n\nhttps://mail.google.com/mail/u/0/#sent/DmwnWrRspPbdmcDnxwQHxSwHHdMFrwzWFKDGWfDFCTwJMbPXphQVkpSPnkJjKTPlCdHrGPWjNtxl"}]$monday$::jsonb) as x(post bigint, contenu text)
where n.monday_post_id = x.post;

commit;

-- Contrôle (attendu : 1 lien tronqué restant au plus, 0 message coupé)
select count(*) filter (where contenu ~ 'https?://\S+\.\.\.') liens_tronques_restants, count(*) filter (where tronque) messages_coupes
from pilotage.travaux_monday_notes;
